
-- AutoRental - Dump MySQL/MariaDB complet
-- Généré à partir du cahier des charges fonctionnel et du dictionnaire de données
-- Compatible avec phpMyAdmin, MySQL 8.x et MariaDB 10.4+
-- Jeu de données déterministe et fictif, sans données personnelles réelles

SET SQL_MODE = 'STRICT_TRANS_TABLES,NO_ZERO_DATE,NO_ZERO_IN_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SET time_zone = '+02:00';
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS `autorental`;
CREATE DATABASE `autorental` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `autorental`;

CREATE TABLE `role` (
  `id_role` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `nom` VARCHAR(50) NOT NULL,
  `description` VARCHAR(255) NULL,
  PRIMARY KEY (`id_role`),
  UNIQUE KEY `uq_role_nom` (`nom`),
  CONSTRAINT `chk_role_nom` CHECK (`nom` IN ('CLIENT','GESTIONNAIRE_COMPTABLE','ADMINISTRATEUR','MECANICIEN','NETTOYEUR'))
) ENGINE=InnoDB;

CREATE TABLE `utilisateur` (
  `id_utilisateur` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_role` INT UNSIGNED NOT NULL,
  `nom` VARCHAR(100) NOT NULL,
  `prenom` VARCHAR(100) NOT NULL,
  `email` VARCHAR(150) NOT NULL,
  `mot_de_passe` VARCHAR(255) NOT NULL,
  `telephone` VARCHAR(20) NULL,
  `date_creation` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actif` BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (`id_utilisateur`),
  UNIQUE KEY `uq_utilisateur_email` (`email`),
  KEY `idx_utilisateur_role` (`id_role`),
  KEY `idx_utilisateur_nom_prenom` (`nom`,`prenom`),
  CONSTRAINT `fk_utilisateur_role` FOREIGN KEY (`id_role`) REFERENCES `role` (`id_role`) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `client` (
  `id_client` INT UNSIGNED NOT NULL,
  `date_naissance` DATE NOT NULL,
  `adresse` VARCHAR(255) NOT NULL,
  `statut_profil` VARCHAR(20) NOT NULL DEFAULT 'INCOMPLET',
  `motif_refus` VARCHAR(255) NULL,
  PRIMARY KEY (`id_client`),
  KEY `idx_client_statut` (`statut_profil`),
  CONSTRAINT `fk_client_utilisateur` FOREIGN KEY (`id_client`) REFERENCES `utilisateur` (`id_utilisateur`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_client_statut` CHECK (`statut_profil` IN ('INCOMPLET','EN_ATTENTE','VALIDE','REFUSE','EXPIRE')),
  CONSTRAINT `chk_client_refus` CHECK (`statut_profil` <> 'REFUSE' OR `motif_refus` IS NOT NULL)
) ENGINE=InnoDB;

CREATE TABLE `document_client` (
  `id_document` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_client` INT UNSIGNED NOT NULL,
  `type_document` VARCHAR(30) NOT NULL,
  `numero_document` VARCHAR(100) NOT NULL,
  `fichier_url` VARCHAR(255) NOT NULL,
  `date_expiration` DATE NOT NULL,
  `statut` VARCHAR(20) NOT NULL DEFAULT 'EN_ATTENTE',
  `motif_refus` VARCHAR(255) NULL,
  `date_depot` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_validation` DATETIME NULL,
  `id_gestionnaire_validateur` INT UNSIGNED NULL,
  `date_creation` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_modification` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `actif` BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (`id_document`),
  UNIQUE KEY `uq_document_type_numero` (`type_document`,`numero_document`),
  KEY `idx_document_client` (`id_client`),
  KEY `idx_document_validateur` (`id_gestionnaire_validateur`),
  KEY `idx_document_statut` (`statut`),
  CONSTRAINT `fk_document_client` FOREIGN KEY (`id_client`) REFERENCES `client` (`id_client`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `fk_document_validateur` FOREIGN KEY (`id_gestionnaire_validateur`) REFERENCES `utilisateur` (`id_utilisateur`) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `chk_document_type` CHECK (`type_document` IN ('CARTE_IDENTITE','PERMIS_CONDUIRE')),
  CONSTRAINT `chk_document_statut` CHECK (`statut` IN ('EN_ATTENTE','VALIDE','REFUSE','EXPIRE')),
  CONSTRAINT `chk_document_refus` CHECK (`statut` <> 'REFUSE' OR `motif_refus` IS NOT NULL)
) ENGINE=InnoDB;

CREATE TABLE `notification` (
  `id_notification` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_utilisateur` INT UNSIGNED NOT NULL,
  `type` VARCHAR(30) NOT NULL,
  `titre` VARCHAR(150) NOT NULL,
  `contenu` TEXT NOT NULL,
  `canal` VARCHAR(20) NOT NULL,
  `date_creation` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_envoi` DATETIME NULL,
  `statut_envoi` VARCHAR(20) NOT NULL DEFAULT 'EN_ATTENTE',
  `lue` BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (`id_notification`),
  KEY `idx_notification_utilisateur` (`id_utilisateur`),
  KEY `idx_notification_type_statut` (`type`,`statut_envoi`),
  CONSTRAINT `fk_notification_utilisateur` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_notification_type` CHECK (`type` IN ('CONFIRMATION','RAPPEL','DOCUMENT','PROFIL','PAIEMENT','RETARD','INTERVENTION','AUTRE')),
  CONSTRAINT `chk_notification_canal` CHECK (`canal` IN ('APPLICATION','EMAIL')),
  CONSTRAINT `chk_notification_statut` CHECK (`statut_envoi` IN ('EN_ATTENTE','ENVOYEE','ECHOUEE'))
) ENGINE=InnoDB;

CREATE TABLE `marque` (
  `id_marque` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `nom` VARCHAR(100) NOT NULL,
  `logo_url` VARCHAR(255) NULL,
  PRIMARY KEY (`id_marque`),
  UNIQUE KEY `uq_marque_nom` (`nom`)
) ENGINE=InnoDB;

CREATE TABLE `categorie_vehicule` (
  `id_categorie` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `nom` VARCHAR(100) NOT NULL,
  `description` VARCHAR(255) NULL,
  `tarif_journalier_base` DECIMAL(10,2) NOT NULL,
  `caution_minimale` DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (`id_categorie`),
  UNIQUE KEY `uq_categorie_nom` (`nom`),
  CONSTRAINT `chk_categorie_tarif` CHECK (`tarif_journalier_base` >= 0),
  CONSTRAINT `chk_categorie_caution` CHECK (`caution_minimale` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `parking` (
  `id_parking` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `nom` VARCHAR(100) NOT NULL,
  `adresse` VARCHAR(255) NOT NULL,
  `capacite` INT UNSIGNED NOT NULL,
  `actif` BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (`id_parking`),
  UNIQUE KEY `uq_parking_nom` (`nom`),
  CONSTRAINT `chk_parking_capacite` CHECK (`capacite` > 0)
) ENGINE=InnoDB;

CREATE TABLE `place_parking` (
  `id_place` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_parking` INT UNSIGNED NOT NULL,
  `numero` VARCHAR(20) NOT NULL,
  `actif` BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (`id_place`),
  UNIQUE KEY `uq_place_parking_numero` (`id_parking`,`numero`),
  KEY `idx_place_parking` (`id_parking`),
  CONSTRAINT `fk_place_parking` FOREIGN KEY (`id_parking`) REFERENCES `parking` (`id_parking`) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `vehicule` (
  `id_vehicule` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_marque` INT UNSIGNED NOT NULL,
  `id_categorie` INT UNSIGNED NOT NULL,
  `modele` VARCHAR(100) NOT NULL,
  `immatriculation` VARCHAR(20) NOT NULL,
  `annee` INT NOT NULL,
  `couleur` VARCHAR(30) NULL,
  `carburant` VARCHAR(30) NOT NULL,
  `boite_vitesse` VARCHAR(20) NOT NULL,
  `nb_places` INT NOT NULL,
  `kilometrage` INT UNSIGNED NOT NULL DEFAULT 0,
  `statut` VARCHAR(20) NOT NULL,
  `localisation_actuelle` VARCHAR(255) NULL,
  `id_place_parking` INT UNSIGNED NOT NULL,
  PRIMARY KEY (`id_vehicule`),
  UNIQUE KEY `uq_vehicule_immatriculation` (`immatriculation`),
  UNIQUE KEY `uq_vehicule_place` (`id_place_parking`),
  KEY `idx_vehicule_marque` (`id_marque`),
  KEY `idx_vehicule_categorie` (`id_categorie`),
  KEY `idx_vehicule_statut` (`statut`),
  CONSTRAINT `fk_vehicule_marque` FOREIGN KEY (`id_marque`) REFERENCES `marque` (`id_marque`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_vehicule_categorie` FOREIGN KEY (`id_categorie`) REFERENCES `categorie_vehicule` (`id_categorie`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_vehicule_place` FOREIGN KEY (`id_place_parking`) REFERENCES `place_parking` (`id_place`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_vehicule_annee` CHECK (`annee` BETWEEN 1980 AND 2027),
  CONSTRAINT `chk_vehicule_carburant` CHECK (`carburant` IN ('ESSENCE','DIESEL','HYBRIDE','ELECTRIQUE','GPL')),
  CONSTRAINT `chk_vehicule_boite` CHECK (`boite_vitesse` IN ('MANUELLE','AUTOMATIQUE')),
  CONSTRAINT `chk_vehicule_places` CHECK (`nb_places` BETWEEN 1 AND 9),
  CONSTRAINT `chk_vehicule_statut` CHECK (`statut` IN ('DISPONIBLE','RESERVE','LOUE','A_CONTROLER','MAINTENANCE','NETTOYAGE','ACCIDENTE','HORS_SERVICE'))
) ENGINE=InnoDB;

CREATE TABLE `photo_vehicule` (
  `id_photo_vehicule` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_vehicule` INT UNSIGNED NOT NULL,
  `url` VARCHAR(255) NOT NULL,
  `description` VARCHAR(255) NULL,
  `ordre` INT UNSIGNED NOT NULL DEFAULT 1,
  `principale` BOOLEAN NOT NULL DEFAULT FALSE,
  `actif` BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (`id_photo_vehicule`),
  KEY `idx_photo_vehicule` (`id_vehicule`),
  CONSTRAINT `fk_photo_vehicule` FOREIGN KEY (`id_vehicule`) REFERENCES `vehicule` (`id_vehicule`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_photo_vehicule_ordre` CHECK (`ordre` >= 1)
) ENGINE=InnoDB;

CREATE TABLE `reservation` (
  `id_reservation` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_client` INT UNSIGNED NOT NULL,
  `id_vehicule` INT UNSIGNED NOT NULL,
  `date_debut` DATETIME NOT NULL,
  `date_fin` DATETIME NOT NULL,
  `statut` VARCHAR(20) NOT NULL,
  `lieu_debut` VARCHAR(255) NOT NULL,
  `lieu_fin` VARCHAR(255) NOT NULL,
  `kilometrage_estime` INT UNSIGNED NULL,
  `montant_estime` DECIMAL(10,2) NOT NULL,
  `date_creation` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_reservation`),
  KEY `idx_reservation_client` (`id_client`),
  KEY `idx_reservation_vehicule` (`id_vehicule`),
  KEY `idx_reservation_dates` (`date_debut`,`date_fin`),
  KEY `idx_reservation_statut` (`statut`),
  CONSTRAINT `fk_reservation_client` FOREIGN KEY (`id_client`) REFERENCES `client` (`id_client`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_reservation_vehicule` FOREIGN KEY (`id_vehicule`) REFERENCES `vehicule` (`id_vehicule`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_reservation_dates` CHECK (`date_fin` > `date_debut`),
  CONSTRAINT `chk_reservation_statut` CHECK (`statut` IN ('BROUILLON','CONFIRMEE','EN_COURS','TERMINEE','ANNULEE','EXPIREE')),
  CONSTRAINT `chk_reservation_montant` CHECK (`montant_estime` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `etat_des_lieux` (
  `id_etat_lieu` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NOT NULL,
  `type` VARCHAR(10) NOT NULL,
  `date_heure` DATETIME NOT NULL,
  `kilometrage` INT UNSIGNED NOT NULL,
  `niveau_carburant` VARCHAR(20) NOT NULL,
  `remarques` TEXT NULL,
  PRIMARY KEY (`id_etat_lieu`),
  UNIQUE KEY `uq_etat_reservation_type` (`id_reservation`,`type`),
  KEY `idx_etat_reservation` (`id_reservation`),
  CONSTRAINT `fk_etat_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_etat_type` CHECK (`type` IN ('INITIAL','FINAL')),
  CONSTRAINT `chk_etat_carburant` CHECK (`niveau_carburant` IN ('VIDE','1/4','1/2','3/4','PLEIN') OR `niveau_carburant` REGEXP '^[0-9]{1,3}%$')
) ENGINE=InnoDB;

CREATE TABLE `photo_etat` (
  `id_photo` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_etat_lieu` INT UNSIGNED NOT NULL,
  `url` VARCHAR(255) NOT NULL,
  `description` VARCHAR(255) NULL,
  `ordre` INT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_photo`),
  KEY `idx_photo_etat` (`id_etat_lieu`),
  CONSTRAINT `fk_photo_etat` FOREIGN KEY (`id_etat_lieu`) REFERENCES `etat_des_lieux` (`id_etat_lieu`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_photo_etat_ordre` CHECK (`ordre` >= 1)
) ENGINE=InnoDB;

CREATE TABLE `dommage` (
  `id_dommage` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NOT NULL,
  `id_etat_lieu` INT UNSIGNED NOT NULL,
  `description` TEXT NOT NULL,
  `responsabilite` VARCHAR(20) NOT NULL,
  `cout_estime` DECIMAL(10,2) NULL,
  `statut` VARCHAR(20) NOT NULL,
  `date_declaration` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_dommage`),
  KEY `idx_dommage_reservation` (`id_reservation`),
  KEY `idx_dommage_etat` (`id_etat_lieu`),
  KEY `idx_dommage_statut` (`statut`),
  CONSTRAINT `fk_dommage_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_dommage_etat` FOREIGN KEY (`id_etat_lieu`) REFERENCES `etat_des_lieux` (`id_etat_lieu`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_dommage_responsabilite` CHECK (`responsabilite` IN ('CLIENT','TIERS','INTERNE','INCONNUE')),
  CONSTRAINT `chk_dommage_statut` CHECK (`statut` IN ('DECLARE','EN_VERIFICATION','CONFIRME','CONTESTE','CLOTURE')),
  CONSTRAINT `chk_dommage_cout` CHECK (`cout_estime` IS NULL OR `cout_estime` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `paiement` (
  `id_paiement` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NOT NULL,
  `montant` DECIMAL(10,2) NOT NULL,
  `devise` VARCHAR(10) NOT NULL DEFAULT 'EUR',
  `statut` VARCHAR(20) NOT NULL,
  `methode` VARCHAR(20) NOT NULL,
  `transaction_id` VARCHAR(100) NULL,
  `date_paiement` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_paiement`),
  UNIQUE KEY `uq_paiement_transaction` (`transaction_id`),
  KEY `idx_paiement_reservation` (`id_reservation`),
  KEY `idx_paiement_statut_date` (`statut`,`date_paiement`),
  CONSTRAINT `fk_paiement_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_paiement_montant` CHECK (`montant` > 0),
  CONSTRAINT `chk_paiement_statut` CHECK (`statut` IN ('EN_ATTENTE','REUSSI','ECHOUE')),
  CONSTRAINT `chk_paiement_methode` CHECK (`methode` IN ('CARTE','VIREMENT'))
) ENGINE=InnoDB;

CREATE TABLE `remboursement` (
  `id_remboursement` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_paiement` INT UNSIGNED NOT NULL,
  `id_gestionnaire` INT UNSIGNED NULL,
  `montant` DECIMAL(10,2) NOT NULL,
  `type` VARCHAR(20) NOT NULL,
  `motif` VARCHAR(255) NOT NULL,
  `reference_externe` VARCHAR(100) NULL,
  `statut` VARCHAR(20) NOT NULL DEFAULT 'DEMANDE',
  `date_demande` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_execution` DATETIME NULL,
  PRIMARY KEY (`id_remboursement`),
  UNIQUE KEY `uq_remboursement_reference` (`reference_externe`),
  KEY `idx_remboursement_paiement` (`id_paiement`),
  KEY `idx_remboursement_gestionnaire` (`id_gestionnaire`),
  KEY `idx_remboursement_statut` (`statut`),
  CONSTRAINT `fk_remboursement_paiement` FOREIGN KEY (`id_paiement`) REFERENCES `paiement` (`id_paiement`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_remboursement_gestionnaire` FOREIGN KEY (`id_gestionnaire`) REFERENCES `utilisateur` (`id_utilisateur`) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `chk_remboursement_montant` CHECK (`montant` > 0),
  CONSTRAINT `chk_remboursement_type` CHECK (`type` IN ('TOTAL','PARTIEL')),
  CONSTRAINT `chk_remboursement_statut` CHECK (`statut` IN ('DEMANDE','EN_COURS','REUSSI','ECHOUE','ANNULE'))
) ENGINE=InnoDB;

CREATE TABLE `caution` (
  `id_caution` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NOT NULL,
  `montant` DECIMAL(10,2) NOT NULL,
  `statut` VARCHAR(20) NOT NULL,
  `date_demande` DATETIME NOT NULL,
  `date_autorisation` DATETIME NULL,
  `date_liberation` DATETIME NULL,
  `transaction_id` VARCHAR(100) NULL,
  PRIMARY KEY (`id_caution`),
  UNIQUE KEY `uq_caution_reservation` (`id_reservation`),
  UNIQUE KEY `uq_caution_transaction` (`transaction_id`),
  KEY `idx_caution_statut` (`statut`),
  CONSTRAINT `fk_caution_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_caution_montant` CHECK (`montant` >= 0),
  CONSTRAINT `chk_caution_statut` CHECK (`statut` IN ('DEMANDEE','AUTORISEE','REFUSEE','LIBEREE','RETENUE'))
) ENGINE=InnoDB;

CREATE TABLE `amende` (
  `id_amende` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NOT NULL,
  `motif` VARCHAR(100) NOT NULL,
  `montant` DECIMAL(10,2) NOT NULL,
  `statut` VARCHAR(20) NOT NULL,
  `date_creation` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_amende`),
  KEY `idx_amende_reservation` (`id_reservation`),
  KEY `idx_amende_statut` (`statut`),
  CONSTRAINT `fk_amende_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_amende_motif` CHECK (`motif` IN ('RETARD','STATIONNEMENT','INFRACTION','CARBURANT','NETTOYAGE','AUTRE')),
  CONSTRAINT `chk_amende_montant` CHECK (`montant` > 0),
  CONSTRAINT `chk_amende_statut` CHECK (`statut` IN ('EMISE','CONTESTEE','CONFIRMEE','PAYEE','ANNULEE'))
) ENGINE=InnoDB;

CREATE TABLE `intervention` (
  `id_intervention` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NULL,
  `id_vehicule` INT UNSIGNED NOT NULL,
  `id_intervenant` INT UNSIGNED NOT NULL,
  `type` VARCHAR(20) NOT NULL,
  `statut` VARCHAR(20) NOT NULL DEFAULT 'PLANIFIEE',
  `date_debut` DATETIME NOT NULL,
  `date_fin` DATETIME NULL,
  `cout_total` DECIMAL(10,2) NULL,
  `remarques` TEXT NULL,
  PRIMARY KEY (`id_intervention`),
  KEY `idx_intervention_reservation` (`id_reservation`),
  KEY `idx_intervention_vehicule` (`id_vehicule`),
  KEY `idx_intervention_intervenant` (`id_intervenant`),
  KEY `idx_intervention_type_statut` (`type`,`statut`),
  CONSTRAINT `fk_intervention_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `fk_intervention_vehicule` FOREIGN KEY (`id_vehicule`) REFERENCES `vehicule` (`id_vehicule`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_intervention_intervenant` FOREIGN KEY (`id_intervenant`) REFERENCES `utilisateur` (`id_utilisateur`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_intervention_type` CHECK (`type` IN ('MECANIQUE','NETTOYAGE')),
  CONSTRAINT `chk_intervention_statut` CHECK (`statut` IN ('PLANIFIEE','ATTRIBUEE','EN_COURS','TERMINEE','ANNULEE')),
  CONSTRAINT `chk_intervention_dates` CHECK (`date_fin` IS NULL OR `date_fin` >= `date_debut`),
  CONSTRAINT `chk_intervention_cout` CHECK (`cout_total` IS NULL OR `cout_total` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `acces_vehicule` (
  `id_acces` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_vehicule` INT UNSIGNED NOT NULL,
  `id_utilisateur` INT UNSIGNED NOT NULL,
  `id_reservation` INT UNSIGNED NULL,
  `id_intervention` INT UNSIGNED NULL,
  `date_debut_validite` DATETIME NOT NULL,
  `date_fin_validite` DATETIME NOT NULL,
  `statut` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`id_acces`),
  KEY `idx_acces_vehicule` (`id_vehicule`),
  KEY `idx_acces_utilisateur` (`id_utilisateur`),
  KEY `idx_acces_reservation` (`id_reservation`),
  KEY `idx_acces_intervention` (`id_intervention`),
  KEY `idx_acces_validite` (`date_debut_validite`,`date_fin_validite`),
  CONSTRAINT `fk_acces_vehicule` FOREIGN KEY (`id_vehicule`) REFERENCES `vehicule` (`id_vehicule`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_acces_utilisateur` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_acces_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `fk_acces_intervention` FOREIGN KEY (`id_intervention`) REFERENCES `intervention` (`id_intervention`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_acces_dates` CHECK (`date_fin_validite` > `date_debut_validite`),
  CONSTRAINT `chk_acces_statut` CHECK (`statut` IN ('ACTIVE','UTILISEE','EXPIREE','ANNULEE')),
  CONSTRAINT `chk_acces_source` CHECK ((`id_reservation` IS NOT NULL AND `id_intervention` IS NULL) OR (`id_reservation` IS NULL AND `id_intervention` IS NOT NULL))
) ENGINE=InnoDB;

CREATE TABLE `journal_verrouillage` (
  `id_journal_verrouillage` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_acces` INT UNSIGNED NOT NULL,
  `action` VARCHAR(20) NOT NULL,
  `date_heure` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `resultat` VARCHAR(20) NOT NULL,
  `message` VARCHAR(255) NULL,
  PRIMARY KEY (`id_journal_verrouillage`),
  KEY `idx_journal_acces` (`id_acces`),
  KEY `idx_journal_date_resultat` (`date_heure`,`resultat`),
  CONSTRAINT `fk_journal_acces` FOREIGN KEY (`id_acces`) REFERENCES `acces_vehicule` (`id_acces`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_journal_action` CHECK (`action` IN ('VERROUILLAGE','DEVERROUILLAGE')),
  CONSTRAINT `chk_journal_resultat` CHECK (`resultat` IN ('REUSSI','ECHOUE'))
) ENGINE=InnoDB;

CREATE TABLE `etat_technique` (
  `id_etat_tech` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_intervention` INT UNSIGNED NOT NULL,
  `type` VARCHAR(10) NOT NULL,
  `date_heure` DATETIME NOT NULL,
  `kilometrage` INT UNSIGNED NOT NULL,
  `description` TEXT NOT NULL,
  `conclusions` TEXT NULL,
  PRIMARY KEY (`id_etat_tech`),
  UNIQUE KEY `uq_etat_tech_intervention_type` (`id_intervention`,`type`),
  KEY `idx_etat_tech_intervention` (`id_intervention`),
  CONSTRAINT `fk_etat_tech_intervention` FOREIGN KEY (`id_intervention`) REFERENCES `intervention` (`id_intervention`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_etat_tech_type` CHECK (`type` IN ('INITIAL','FINAL'))
) ENGINE=InnoDB;

CREATE TABLE `photo_technique` (
  `id_photo_tech` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_etat_tech` INT UNSIGNED NOT NULL,
  `url` VARCHAR(255) NOT NULL,
  `description` VARCHAR(255) NULL,
  `ordre` INT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_photo_tech`),
  KEY `idx_photo_tech_etat` (`id_etat_tech`),
  CONSTRAINT `fk_photo_tech_etat` FOREIGN KEY (`id_etat_tech`) REFERENCES `etat_technique` (`id_etat_tech`) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT `chk_photo_tech_ordre` CHECK (`ordre` >= 1)
) ENGINE=InnoDB;

CREATE TABLE `facture` (
  `id_facture` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_reservation` INT UNSIGNED NOT NULL,
  `type` VARCHAR(20) NOT NULL,
  `montant_total` DECIMAL(10,2) NOT NULL,
  `date_emission` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `statut` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`id_facture`),
  KEY `idx_facture_reservation` (`id_reservation`),
  KEY `idx_facture_type_statut` (`type`,`statut`),
  CONSTRAINT `fk_facture_reservation` FOREIGN KEY (`id_reservation`) REFERENCES `reservation` (`id_reservation`) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `chk_facture_type` CHECK (`type` IN ('LOCATION','DOMMAGE','AMENDE','INTERVENTION')),
  CONSTRAINT `chk_facture_montant` CHECK (`montant_total` >= 0),
  CONSTRAINT `chk_facture_statut` CHECK (`statut` IN ('BROUILLON','EMISE','PAYEE','ANNULEE'))
) ENGINE=InnoDB;


